namespace LeoLauncher;
sealed partial class MusicForm
{
    readonly System.Windows.Forms.Timer syncTimer=new(){Interval=30*60*1000};readonly CancellationTokenSource syncLife=new();readonly HashSet<string> syncing=new();
    public async Task<string> Step(int direction){if(direction is not(-1 or 1))throw new ArgumentException("请选择上一首或下一首");if(queue.Length==0)throw new ArgumentException("还没有当前点歌列表，请先说“听赛前热身”或选择一首歌。");int next=(queueIndex+direction+queue.Length)%queue.Length;if(!await Play(queue[next]))throw new IOException(state.Text);queueIndex=next;return "已发送"+(direction>0?"下一首":"上一首")+"："+queue[next].Name+"。";}
    public async Task<string> PlayByName(string name){static string Key(string text)=>string.Concat(text.Where(c=>!char.IsWhiteSpace(c)&&!char.IsPunctuation(c))).ToLowerInvariant();var matches=library.Items.Where(p=>Key(p.Name)==Key(name)).ToArray();if(matches.Length!=1)throw new ArgumentException(matches.Length>1?"有多个同名歌单，请从右键菜单选择。":"没有这个常听歌单。现有："+string.Join("、",library.Items.Select(p=>p.Name)));if(!await PlayPlaylist(matches[0].Id))throw new IOException("歌单为空或无法发送播放请求，请检查QQ音乐客户端。");return "已发送“"+matches[0].Name+"”的首曲："+queue[0].Name+"。";}
    public async Task SyncDueAsync(){if(preview||IsDisposed)return;foreach(var p in library.Items.Where(p=>p.QQId!=null&&(p.Synced==null||p.Synced<DateTimeOffset.Now.AddHours(-6))).ToArray()){if(syncLife.IsCancellationRequested)return;await SyncOneAsync(p.Id,false);}}
    public async Task SyncOneAsync(string id,bool showStatus=true){var playlist=library.Items.FirstOrDefault(p=>p.Id==id);if(playlist?.QQId==null||!syncing.Add(id))return;if(showStatus)state.Text="正在同步“"+playlist.Name+"”…";try{var data=await QQPlaylists.Fetch(playlist.QQId,syncLife.Token);if(IsDisposed||syncLife.IsCancellationRequested)return;if(!library.Items.Any(p=>p.Id==id))return;library.Import(data,targetId:id);if(Visible)Home();state.Text="已同步“"+playlist.Name+"” · "+data.Songs.Length+"首"+(data.Total>200?"（前200首）":"");}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)state.Text=e.Message;}finally{syncing.Remove(id);}}
    async Task ImportFromPrompt(){using var dialog=new BarcaWindow{Text="导入QQ音乐歌单",ClientSize=new Size(530,252),StartPosition=FormStartPosition.CenterParent};dialog.Controls.Add(BarcaUi.Chrome(dialog,"导入 QQ 歌单","粘贴公开歌单完整链接或编号，定期同步到本地。"));var text=new TextBox{Bounds=new Rectangle(23,111,482,32),BackColor=BarcaUi.Raised,ForeColor=BarcaUi.Text,Font=BarcaUi.Font(10),MaxLength=1200,PlaceholderText="https://y.qq.com/n/ryqq/playlist/…"};var hint=new Label{Bounds=new Rectangle(24,154,480,27),ForeColor=BarcaUi.Muted,Font=BarcaUi.Font(8.5f),Text="仅读取公开歌曲信息；不会修改QQ账号里的歌单。"};var ok=new BarcaButton{Text="导入并置顶",Bounds=new Rectangle(365,194,140,34)};ok.Click+=(_,_)=>{if(QQPlaylists.ExtractId(text.Text)==null){hint.Text="请复制完整的QQ音乐歌单链接，或填写数字歌单编号";return;}dialog.DialogResult=DialogResult.OK;};dialog.Controls.AddRange([text,hint,ok]);dialog.AcceptButton=ok;if(dialog.ShowDialog(this)!=DialogResult.OK)return;string id=QQPlaylists.ExtractId(text.Text)!;state.Text="正在读取QQ歌单…";try{var data=await QQPlaylists.Fetch(id,syncLife.Token);if(IsDisposed)return;library.Import(data);Home();state.Text="已导入并绑定“"+data.Name+"” · "+data.Songs.Length+"首";}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed)state.Text=e.Message;}}
}
sealed partial class PetForm
{
    bool lyricsHotkeyRegistered;
    async Task ToggleLyricsWithFeedback(){try{if(!previewMode)await QQNative.ToggleLyrics();}catch(Exception e){tray.BalloonTipTitle="Leo · 桌面歌词";tray.BalloonTipText=e.Message;tray.ShowBalloonTip(5000);}}
    void WireMusicMenu(ContextMenuStrip menu){var musicRoot=new ToolStripMenuItem("音乐");var drop=(ToolStripDropDownMenu)musicRoot.DropDown;drop.Renderer=new BarcaMenuRenderer();drop.BackColor=BarcaUi.Surface;drop.ForeColor=BarcaUi.Text;drop.Font=BarcaUi.Font(9.5f);drop.ShowImageMargin=false;drop.ShowCheckMargin=false;void Refresh(){foreach(var item in musicRoot.DropDownItems.Cast<ToolStripItem>().ToArray())item.Dispose();musicRoot.DropDownItems.Clear();var panel=launcher.MusicWithoutOpening();foreach(var playlist in panel.Library.Items.Where(p=>p.Pinned)){string id=playlist.Id;var item=new ToolStripMenuItem(playlist.Name);item.Click+=async(_,_)=>{try{if(!await panel.PlayPlaylist(id))throw new IOException("歌单为空或QQ音乐未能就绪");}catch(Exception e){tray.BalloonTipTitle="Leo · 点歌";tray.BalloonTipText=e.Message;tray.ShowBalloonTip(5000);}};musicRoot.DropDownItems.Add(item);}if(musicRoot.DropDownItems.Count==0)musicRoot.DropDownItems.Add(new ToolStripMenuItem("暂无置顶歌单"){Enabled=false});musicRoot.DropDownItems.Add(new ToolStripSeparator());musicRoot.DropDownItems.Add("随手听…",null,(_,_)=>launcher.OpenMusicFromAssistant());var lyric=new ToolStripMenuItem("显示 / 隐藏歌词"){ShortcutKeyDisplayString=lyricsHotkeyRegistered?LeoHotkeys.Display(prefs.LyricsHotkey):""};lyric.Click+=async(_,_)=>await ToggleLyricsWithFeedback();musicRoot.DropDownItems.Add(lyric);foreach(ToolStripItem item in musicRoot.DropDownItems){if(item is ToolStripSeparator)continue;item.AutoSize=false;item.Size=new Size(290,37);item.Padding=new Padding(10,0,10,0);}}musicRoot.DropDownItems.Add("置顶歌单");menu.Opening+=(_,_)=>Refresh();menu.Items.Insert(Math.Max(0,menu.Items.Count-1),musicRoot);BarcaMenus.Apply(menu);}
}
